<?php
require_once __DIR__ . '/inc/config.php'; require_once __DIR__ . '/inc/auth.php'; require_once __DIR__ . '/inc/csrf.php'; require_login();
$id=(int)($_GET['id']??0); $editing=$id>0; $tool=null; if($editing){$s=$pdo->prepare('SELECT * FROM technology_tools WHERE id=?');$s->execute([$id]);$tool=$s->fetch();}
$errors=[]; if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$title=trim($_POST['title']??'');$description=trim($_POST['description']??'');$sort=(int)($_POST['sort_order']??0);$image=$tool['image']??null;if(!$title)$errors[]='Tool name is required.';if(!empty($_FILES['image'])&&$_FILES['image']['error']===UPLOAD_ERR_OK){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/svg+xml'=>'svg'];if(!isset($allowed[$mime]))$errors[]='Invalid image type.';else{$new=bin2hex(random_bytes(8)).'.'.$allowed[$mime];if(!move_uploaded_file($_FILES['image']['tmp_name'],UPLOAD_DIR_TOOLS.$new))$errors[]='Upload failed.';else{if($image&&file_exists(UPLOAD_DIR_TOOLS.$image))@unlink(UPLOAD_DIR_TOOLS.$image);$image=$new;}}}if(!$errors){if($editing){$s=$pdo->prepare('UPDATE technology_tools SET title=?,description=?,image=?,sort_order=? WHERE id=?');$s->execute([$title,$description,$image,$sort,$id]);}else{$s=$pdo->prepare('INSERT INTO technology_tools(title,description,image,sort_order) VALUES(?,?,?,?)');$s->execute([$title,$description,$image,$sort]);}header('Location: tools.php');exit;}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $editing?'Edit':'Add' ?> Tool</title><link rel="stylesheet" href="../css/style.css"></head><body><nav style="padding:1rem;background:#0b0b0b;color:#fff"><a href="index.php" style="color:#fff;margin-right:1rem">Dashboard</a><a href="tools.php" style="color:#fff;margin-right:1rem">Software & Technology</a><a href="logout.php" style="float:right;color:#fff">Logout</a></nav><main class="container"><h1><?= $editing?'Edit':'Add' ?> Tool</h1><?php foreach($errors as $error): ?><p style="color:tomato"><?=e($error)?></p><?php endforeach; ?><form method="post" enctype="multipart/form-data"><?php echo csrf_field(); ?><label>Tool name<br><input name="title" required value="<?=e($tool['title']??'')?>"></label><label>Description<br><input name="description" value="<?=e($tool['description']??'')?>" placeholder="Experienced - photo editing"></label><label>Order<br><input type="number" name="sort_order" value="<?=e($tool['sort_order']??0)?>"></label><label>Image or icon<br><input type="file" name="image" accept="image/png,image/jpeg,image/webp,image/svg+xml"></label><?php if(!empty($tool['image'])): ?><p>Current: <img src="../assets/uploads/tools/<?=e($tool['image'])?>" style="width:64px;height:64px;object-fit:contain;background:#fff;padding:4px"></p><?php endif; ?><button class="btn btn-primary" type="submit">Save</button></form></main></body></html>
